  group=document.createElement('div');group.id='riBosanskiTexts';bs.before(group);
  for(const [id,cls,lang] of []){
   const p=document.createElement('p');p.id=id;p.className=cls;p.lang=lang;if(lang==='ar')p.dir='rtl';group.append(p);
  }
